// Autonomic Mastery Knowledge Base — Part 1 (builder + Java, Systems Analysis, Maths)
// Each entry is a compact expert record expanded into a full 8-step mastery lesson:
// [title, definition, real-world analogy, mnemonic, code/example, quizQ, correct, wrong1, wrong2]
import type { LessonStep } from "./lessons";

export type TopicRecord = [string, string, string, string, string, string, string, string, string];

function q(
  title: string,
  question: string,
  options: { label: string; text: string }[],
  correct: string,
  explanation: string,
  difficulty: "easy" | "medium" | "hard" = "medium"
): LessonStep {
  return { type: "quiz", title, difficulty, question, options, correctAnswer: correct, explanation };
}

function t(
  title: string,
  prompt: string,
  code: string,
  explanation: string,
  difficulty: "easy" | "medium" | "hard" = "easy"
): LessonStep {
  return { type: "typing", title, difficulty, prompt, codeToType: code, explanation };
}

function shuffleOptions(correct: string, wrong1: string, wrong2: string) {
  return [
    { label: "A", text: correct },
    { label: "B", text: wrong1 },
    { label: "C", text: wrong2 },
  ];
}

/**
 * Expands one compact topic record into an 8-step autonomic mastery lesson.
 * Cycle: Hook -> Plain definition -> Analogy -> Guided drill -> Mnemonic ->
 *        Application quiz -> Repetition drill -> Speed mastery check.
 */
export function buildMasterySteps(rec: TopicRecord): LessonStep[] {
  const [title, definition, analogy, mnemonic, example, quizQ, correct, wrong1, wrong2] = rec;
  return [
    q(
      `Why ${title} matters`,
      `Imagine you are starting from zero knowledge. Why do people learn ${title}?`,
      shuffleOptions(definition, `It is an outdated idea nobody uses today`, `It only matters for computer repair shops`),
      "A",
      `${title}: ${definition} Every expert started exactly where you are now — one small idea at a time.`,
      "easy"
    ),
    q(
      `${title} in plain words`,
      `Explain ${title} to a 10-year-old. Which sentence is right?`,
      shuffleOptions(definition, `It is a way to make your screen brighter`, `It is a type of computer virus`),
      "A",
      `Correct. Say it out loud once: "${definition}" Saying it aloud builds the memory trace faster than reading.`,
      "easy"
    ),
    q(
      `Picture it: ${title}`,
      `Which everyday picture matches ${title}?`,
      shuffleOptions(analogy, `A locked door with no key`, `A blank sheet of paper`),
      "A",
      `Your brain stores pictures far better than words. Keep this image: ${analogy}`,
      "easy"
    ),
    t(
      `Guided drill: ${title}`,
      `Type this out slowly and read each part as you go:`,
      example,
      `That is the core pattern for ${title}. Typing it — not just reading — is what moves it into muscle memory.`,
      "easy"
    ),
    q(
      `Memory hook: ${title}`,
      `Which memory hook locks in ${title}?`,
      shuffleOptions(mnemonic, `Just try to remember it word for word`, `Look it up every single time`),
      "A",
      `Mnemonic: ${mnemonic} — repeat it three times now. Spaced repetition will do the rest.`,
      "easy"
    ),
    q(
      `Use it: ${title}`,
      quizQ,
      shuffleOptions(correct, wrong1, wrong2),
      "A",
      `${correct} — that is exactly how a professional would answer. ${definition}`,
      "medium"
    ),
    t(
      `Repetition drill: ${title}`,
      `Type the pattern again from memory — glance away first, then check:`,
      example,
      `Second pass. Recall-then-check is the single strongest study technique we have evidence for.`,
      "medium"
    ),
    t(
      `Mastery check: ${title}`,
      `Final speed run. Type it fluently, no pauses:`,
      example,
      `Mastered. You can now use ${title} without thinking about it — that is autonomy. ${mnemonic}`,
      "hard"
    ),
  ];
}

